/* =========================================================
   Bakerz Bite – Location (open status + delivery radar) and
      FAQ (recipe box: search, tabs, animated cards).
         Everything is wrapped so it never clashes with bakerz-app.js.
            ========================================================= */
            (function () {
              'use strict';

                const q  = (s, r) => (r || document).querySelector(s);
                  const qa = (s, r) => Array.from((r || document).querySelectorAll(s));
                    const esc = s => String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

                      /* ---------- Settings you can change ---------- */
                        const TZ = 'Asia/Karachi';
                          const OPEN_MIN = 9 * 60;        // 9:00 AM
                            const CLOSE_MIN = 22 * 60;      // 10:00 PM
                              const PREP_MIN = 25;            // baking + packing time (minutes)
                                const MIN_PER_KM = 3;           // rough travel time per km (minutes)

                                  /* =====================================================
                                       1) LIVE OPEN / CLOSED STATUS  (location page)
                                            ===================================================== */
                                              function karachiMinutes() {
                                                  const parts = new Intl.DateTimeFormat('en-GB', { timeZone: TZ, hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).formatToParts(new Date());
                                                      let h = 0, m = 0;
                                                          parts.forEach(p => { if (p.type === 'hour') h = +p.value; if (p.type === 'minute') m = +p.value; });
                                                              return h * 60 + m;
                                                                }
                                                                  function span(mins) {
                                                                      const h = Math.floor(mins / 60), m = mins % 60;
                                                                          return h ? (m ? h + ' h ' + m + ' min' : h + ' h') : m + ' min';
                                                                            }
                                                                              function initStatus() {
                                                                                  const box = q('#lxStatus'), txt = q('#lxStatusText');
                                                                                      if (!box || !txt) return;
                                                                                          const paint = () => {
                                                                                                const t = karachiMinutes();
                                                                                                      if (t >= OPEN_MIN && t < CLOSE_MIN) {
                                                                                                              box.className = 'lx-status is-open';
                                                                                                                      txt.textContent = 'Open now. We close at 10:00 PM, in ' + span(CLOSE_MIN - t) + '.';
                                                                                                                            } else {
                                                                                                                                    const wait = t < OPEN_MIN ? OPEN_MIN - t : 1440 - t + OPEN_MIN;
                                                                                                                                            box.className = 'lx-status is-closed';
                                                                                                                                                    txt.textContent = 'Closed right now. We open at 9:00 AM, in ' + span(wait) + '.';
                                                                                                                                                          }
                                                                                                                                                              };
                                                                                                                                                                  paint();
                                                                                                                                                                      setInterval(paint, 30000);
                                                                                                                                                                        }

                                                                                                                                                                          /* =====================================================
                                                                                                                                                                               2) DELIVERY RADAR  (location page)
                                                                                                                                                                                    ===================================================== */
                                                                                                                                                                                      function initRadar() {
                                                                                                                                                                                          const host = q('#lxPlateHost');
                                                                                                                                                                                              if (!host || typeof ORDER_DATA === 'undefined') return;

                                                                                                                                                                                                  const branch = (ORDER_DATA.branches.Karachi || [])[0];
                                                                                                                                                                                                      const areas = (ORDER_DATA.areas.Karachi || []).slice();
                                                                                                                                                                                                          if (!branch || !areas.length) return;

                                                                                                                                                                                                              const KEY = (typeof ORDER_KEY !== 'undefined') ? ORDER_KEY : 'bakerzOrderPref';
                                                                                                                                                                                                                  const CX = 300, CY = 300;
                                                                                                                                                                                                                      const rad = Math.PI / 180;

                                                                                                                                                                                                                          const offset = (lat, lng) => ({
                                                                                                                                                                                                                                dx: (lng - branch.lng) * 111.32 * Math.cos(branch.lat * rad),
                                                                                                                                                                                                                                      dy: (lat - branch.lat) * 110.57
                                                                                                                                                                                                                                          });
                                                                                                                                                                                                                                              const distKm = (lat, lng) => { const o = offset(lat, lng); return Math.hypot(o.dx, o.dy); };

                                                                                                                                                                                                                                                  const maxKm = Math.max.apply(null, areas.map(a => distKm(a.lat, a.lng))) * 1.04;
                                                                                                                                                                                                                                                      const scale = 236 / maxKm;
                                                                                                                                                                                                                                                          const pos = (lat, lng) => { const o = offset(lat, lng); return { x: CX + o.dx * scale, y: CY - o.dy * scale }; };

                                                                                                                                                                                                                                                              /* --- build the plate --- */
                                                                                                                                                                                                                                                                  let rings = '';
                                                                                                                                                                                                                                                                      for (let k = 5; k <= maxKm; k += 5) {
                                                                                                                                                                                                                                                                            const r = k * scale;
                                                                                                                                                                                                                                                                                  rings += '<circle class="lx-p-ring" cx="' + CX + '" cy="' + CY + '" r="' + r.toFixed(1) + '"/>' +
                                                                                                                                                                                                                                                                                                 '<text class="lx-p-ringlabel" x="' + (CX - r + 6).toFixed(1) + '" y="' + (CY - 7) + '">' + k + ' km</text>';
                                                                                                                                                                                                                                                                                                     }
                                                                                                                                                                                                                                                                                                         const dots = areas.map((a, i) => {
                                                                                                                                                                                                                                                                                                               if (distKm(a.lat, a.lng) < 0.5) return '';   // the kitchen itself: the logo marks this spot
                                                                                                                                                                                                                                                                                                                     const p = pos(a.lat, a.lng);
                                                                                                                                                                                                                                                                                                                           const ly = p.y < 72 ? p.y + 30 : p.y - 16;
                                                                                                                                                                                                                                                                                                                                 const lx = Math.min(520, Math.max(80, p.x));
                                                                                                                                                                                                                                                                                                                                       return '<g class="lx-dotbtn" data-i="' + i + '"><circle class="lx-hit" cx="' + p.x.toFixed(1) + '" cy="' + p.y.toFixed(1) + '" r="18"/>' +
                                                                                                                                                                                                                                                                                                                                                    '<circle class="lx-d" cx="' + p.x.toFixed(1) + '" cy="' + p.y.toFixed(1) + '" r="7"/>' +
                                                                                                                                                                                                                                                                                                                                                                 '<text class="lx-lab" x="' + lx.toFixed(1) + '" y="' + ly.toFixed(1) + '">' + esc(a.name) + '</text></g>';
                                                                                                                                                                                                                                                                                                                                                                     }).join('');

                                                                                                                                                                                                                                                                                                                                                                         host.innerHTML =
                                                                                                                                                                                                                                                                                                                                                                               '<svg class="lx-plate" id="lxPlate" viewBox="0 0 600 600" role="img" aria-label="Round map of Karachi areas around our North Nazimabad kitchen. Use the area buttons to explore it.">' +
                                                                                                                                                                                                                                                                                                                                                                                       '<circle class="lx-p-crust" cx="300" cy="300" r="292"/>' +
                                                                                                                                                                                                                                                                                                                                                                                               '<circle class="lx-p-crimp-lo" cx="300" cy="300" r="279"/>' +
                                                                                                                                                                                                                                                                                                                                                                                                       '<circle class="lx-p-crimp-hi" cx="300" cy="300" r="279"/>' +
                                                                                                                                                                                                                                                                                                                                                                                                               '<circle class="lx-p-fill" cx="300" cy="300" r="266"/>' +
                                                                                                                                                                                                                                                                                                                                                                                                                       rings +
                                                                                                                                                                                                                                                                                                                                                                                                                               '<text class="lx-p-north" x="300" y="46">N</text>' +
                                                                                                                                                                                                                                                                                                                                                                                                                                       '<g id="lxRoute"></g>' +
                                                                                                                                                                                                                                                                                                                                                                                                                                               '<circle class="lx-p-core" cx="300" cy="300" r="37"/>' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                       '<image href="../images/logo-bakerz-bite.png?v=4" x="268" y="268" width="64" height="64"/>' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                               '<g id="lxDots">' + dots + '</g><g id="lxYou"></g>' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                     '</svg>';

                                                                                                                                                                                                                                                                                                                                                                                                                                                                         /* --- chips --- */
                                                                                                                                                                                                                                                                                                                                                                                                                                                                             const chipsBox = q('#lxChips');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 chipsBox.innerHTML = areas.map((a, i) => '<button class="lx-chip" type="button" data-i="' + i + '" aria-pressed="false">' + esc(a.name) + '</button>').join('');

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     const result = q('#lxResult');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         const emptyHTML = '<p class="lx-empty">Choose your area, or tap a dot on the plate, to see how far our kitchen is and how long delivery usually takes.</p>';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             result.innerHTML = emptyHTML;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 const routeLayer = q('#lxRoute'), youLayer = q('#lxYou'), dotLayer = q('#lxDots');

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     function clearMarks() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           routeLayer.innerHTML = ''; youLayer.innerHTML = '';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 qa('.lx-dotbtn', host).forEach(g => g.classList.remove('is-on'));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       qa('.lx-chip', chipsBox).forEach(c => c.setAttribute('aria-pressed', 'false'));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             q('.lx-p-core', host).classList.remove('is-on');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     function drawRoute(p) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           routeLayer.innerHTML = '<path class="lx-p-route draw" pathLength="1" d="M' + CX + ' ' + CY + ' L' + p.x.toFixed(1) + ' ' + p.y.toFixed(1) + '"/>';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   function eta(km) { const e = Math.round((PREP_MIN + MIN_PER_KM * km) / 5) * 5; return e + '–' + (e + 10) + ' min'; }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       function nearestArea(lat, lng) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             let best = areas[0], bd = Infinity;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   areas.forEach(a => { const d = Math.hypot((a.lat - lat) * 110.57, (a.lng - lng) * 100.9); if (d < bd) { bd = d; best = a; } });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         return best;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 function dirLink(lat, lng) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       return 'https://www.google.com/maps/dir/?api=1&origin=' + lat + ',' + lng + '&destination=' + encodeURIComponent(branch.address);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               function saveAndOrder(placeName) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             localStorage.setItem(KEY, JSON.stringify({ type: 'delivery', city: 'Karachi', place: placeName, savedAt: new Date().toISOString() }));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     sessionStorage.setItem('bakerzOrderSession', '1');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           } catch (e) { /* storage blocked – just continue */ }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 location.href = 'menu.html';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         function showResult(title, km, lat, lng, orderPlace, orderLabel) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               const near = km < 0.5;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     result.innerHTML =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             '<h3>' + esc(title) + '</h3>' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     '<dl class="lx-stats">' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               '<div><dt>Distance from our kitchen</dt><dd>' + (near ? 'Under 1 km' : km.toFixed(1) + ' km') + '</dd></div>' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         '<div><dt>Usual delivery time</dt><dd>' + eta(km) + '</dd></div>' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 '</dl>' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         '<div class="lx-actions">' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   '<button class="btn btn-primary" type="button" id="lxOrder">' + esc(orderLabel) + '</button>' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             '<a class="btn btn-outline" target="_blank" rel="noopener" href="' + dirLink(lat, lng) + '">Get directions</a>' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     '</div>' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             '<p class="form-note">Straight-line distance. Times are estimates and change with traffic and order size.</p>';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   q('#lxOrder', result).addEventListener('click', () => saveAndOrder(orderPlace));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           function selectArea(i) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 const a = areas[i]; if (!a) return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       clearMarks();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             const g = dotLayer.querySelector('.lx-dotbtn[data-i="' + i + '"]');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   if (g) { g.classList.add('is-on'); dotLayer.appendChild(g); }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         const chip = chipsBox.querySelector('.lx-chip[data-i="' + i + '"]');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               if (chip) chip.setAttribute('aria-pressed', 'true');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     if (distKm(a.lat, a.lng) < 0.5) q('.lx-p-core', host).classList.add('is-on'); else drawRoute(pos(a.lat, a.lng));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           showResult(a.name, distKm(a.lat, a.lng), a.lat, a.lng, a.name, 'Order delivery to ' + a.name);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   chipsBox.addEventListener('click', e => { const c = e.target.closest('.lx-chip'); if (c) selectArea(+c.dataset.i); });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       host.addEventListener('click', e => { const g = e.target.closest('.lx-dotbtn'); if (g) selectArea(+g.dataset.i); });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           /* --- "Use my location" --- */
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               const locBtn = q('#lxLocate');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   locBtn.addEventListener('click', () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         if (!navigator.geolocation) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 result.innerHTML = '<h3>Location is not available</h3><p class="lx-empty">This browser can\'t share your location. Please pick your area from the list.</p>';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     locBtn.disabled = true; locBtn.textContent = 'Finding you…';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           navigator.geolocation.getCurrentPosition(pos0 => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   locBtn.disabled = false; locBtn.textContent = 'Use my location';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           const lat = pos0.coords.latitude, lng = pos0.coords.longitude;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   const km = distKm(lat, lng);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           clearMarks();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   if (km > maxKm * 1.15) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             result.innerHTML =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         '<h3>You\'re about ' + km.toFixed(0) + ' km away</h3>' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     '<p class="lx-empty">That\'s a little beyond the areas we list for delivery. Message us and we\'ll tell you what\'s possible.</p>' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 '<div class="lx-actions"><a class="btn btn-primary" href="contact.html">Contact the bakery</a></div>';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           const p = pos(lat, lng);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   youLayer.innerHTML = '<g class="lx-you"><circle class="lx-you-pulse" cx="' + p.x.toFixed(1) + '" cy="' + p.y.toFixed(1) + '" r="9"/><circle class="lx-you-dot" cx="' + p.x.toFixed(1) + '" cy="' + p.y.toFixed(1) + '" r="8"/></g>';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           drawRoute(p);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   const near = nearestArea(lat, lng);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           showResult('Your location', km, lat, lng, near.name, 'Order delivery to ' + near.name);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 }, () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         locBtn.disabled = false; locBtn.textContent = 'Use my location';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 result.innerHTML = '<h3>We couldn\'t read your location</h3><p class="lx-empty">Allow location access in your browser, or pick your area from the list.</p>';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       }, { timeout: 8000 });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               /* --- greet returning visitors with their saved area --- */
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         const saved = JSON.parse(localStorage.getItem(KEY));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               if (saved && saved.type === 'delivery') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       const idx = areas.findIndex(a => a.name === saved.place);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               if (idx > -1) selectArea(idx);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         } catch (e) { /* ignore */ }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             /* =====================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  3) FAQ  (faq page) – simple open / close list
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       ===================================================== */
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         function initFaq() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             const list = q('#fqList');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 if (!list) return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     const items = qa('.fq-item', list);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         function setOpen(item, open) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               item.classList.toggle('is-open', open);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     q('.fq-q', item).setAttribute('aria-expanded', String(open));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           const a = q('.fq-a', item);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 if (open) a.removeAttribute('inert'); else a.setAttribute('inert', '');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         items.forEach(i => setOpen(i, false));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             list.addEventListener('click', e => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   const b = e.target.closest('.fq-q');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         if (!b) return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               const item = b.closest('.fq-item');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     setOpen(item, !item.classList.contains('is-open'));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             function fromHash() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   const item = items.find(i => i.id === decodeURIComponent(location.hash.slice(1)));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         if (!item) return false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               setOpen(item, true);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     setTimeout(() => item.scrollIntoView({ behavior: 'smooth', block: 'center' }), 60);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           return true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   fromHash(); /* pehla FAQ ab by default open nahi hota — sab band rehte hain jab tak user khud na khole */
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       window.addEventListener('hashchange', fromHash);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           document.addEventListener('DOMContentLoaded', () => { initStatus(); initRadar(); initFaq(); });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           })();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           